    94	func loadExternalImportRecords(sourcePath string, overrideKind externalImportKind) ([]map[string]any, externalImportKind, error) {
    95		raw, err := os.ReadFile(sourcePath)
    96		if err != nil {
    97			return nil, "", fmt.Errorf("read source %s: %w", sourcePath, err)
    98		}
    99	
   100		kind := overrideKind
   101		if kind == "" {
   102			kind, err = detectExternalImportKind(sourcePath, raw)
   103			if err != nil {
   104				return nil, "", err
   105			}
   106		}
   107	
   108		switch kind {
   109		case externalImportRapidMLXMHI:
   110			record, err := parseRapidMLXMHIImport(sourcePath, raw)
   111			if err != nil {
   112				return nil, kind, err
   113			}
   114			return []map[string]any{record}, kind, nil
   115		case externalImportSkillsBench:
   116			records, err := parseSkillsBenchImport(sourcePath, raw)
   117			if err != nil {
   118				return nil, kind, err
   119			}
   120			return records, kind, nil
   121		case externalImportSWEBench:
   122			records, err := parseSWEBenchImport(sourcePath, raw)
   123			if err != nil {
   124				return nil, kind, err
   125			}
   126			return records, kind, nil
   127		case externalImportHumanEval:
   128			records, err := parseHumanEvalImport(sourcePath, raw)
   129			if err != nil {
   130				return nil, kind, err
   131			}
   132			return records, kind, nil
   133		default:
   134			return nil, "", fmt.Errorf("unsupported external benchmark kind %q", kind)
   135		}
   136	}
