   138	func detectExternalImportKind(sourcePath string, raw []byte) (externalImportKind, error) {
   139		switch strings.ToLower(filepath.Ext(sourcePath)) {
   140		case ".csv":
   141			return externalImportSkillsBench, nil
   142		case ".jsonl":
   143			lower := strings.ToLower(string(raw))
   144			switch {
   145			case strings.Contains(lower, "humaneval") || strings.Contains(lower, "pass_at_") || strings.Contains(lower, "pass@"):
   146				return externalImportHumanEval, nil
   147			case strings.Contains(lower, "swe-bench") || strings.Contains(lower, "resolved_rate") || strings.Contains(lower, "resolved rate"):
   148				return externalImportSWEBench, nil
   149			case strings.Contains(lower, "rapid-mlx") || strings.Contains(lower, "\"mhi\""):
   150				return externalImportRapidMLXMHI, nil
   151			}
   152		case ".json":
   153			lower := strings.ToLower(string(raw))
   154			switch {
   155			case strings.Contains(lower, "rapid-mlx") || strings.Contains(lower, "\"mhi\""):
   156				return externalImportRapidMLXMHI, nil
   157			case strings.Contains(lower, "humaneval") || strings.Contains(lower, "pass_at_") || strings.Contains(lower, "pass@"):
   158				return externalImportHumanEval, nil
   159			case strings.Contains(lower, "swe-bench") || strings.Contains(lower, "resolved_rate") || strings.Contains(lower, "resolved rate"):
   160				return externalImportSWEBench, nil
   161			}
   162		}
   163	
   164		base := strings.ToLower(filepath.Base(sourcePath))
   165		switch {
   166		case strings.Contains(base, "skillsbench"):
   167			return externalImportSkillsBench, nil
   168		case strings.Contains(base, "swe"):
   169			return externalImportSWEBench, nil
   170		case strings.Contains(base, "humaneval"):
   171			return externalImportHumanEval, nil
   172		case strings.Contains(base, "rapid") || strings.Contains(base, "mhi"):
   173			return externalImportRapidMLXMHI, nil
   174		default:
   175			return "", fmt.Errorf("could not infer external benchmark kind for %s; pass --kind", sourcePath)
   176		}
   177	}
